import{_ as a,o as t,c as e,ai as o}from"./chunks/framework.ampVZV4B.js";const g=JSON.parse('{"title":"Python 面试 · 高频快答","description":"","frontmatter":{},"headers":[],"relativePath":"guide/python/quick-qa.md","filePath":"guide/python/quick-qa.md"}'),n={name:"guide/python/quick-qa.md"};function s(h,r,i,p,c,d){return t(),e("div",null,[...r[0]||(r[0]=[o('<h1 id="python-面试-·-高频快答" tabindex="-1">Python 面试 · 高频快答 <a class="header-anchor" href="#python-面试-·-高频快答" aria-label="Permalink to “Python 面试 · 高频快答”">​</a></h1><blockquote><p>一面速过。展开见同目录其它页。</p></blockquote><hr><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to “定位”">​</a></h2><p><strong>Q：你会 Python 吗？到什么程度？</strong><br> A：能写脚本和工具：语法、常用库、venv、调 HTTP API；不是专职 Python 后端，复杂业务仍用 Java。</p><p><strong>Q：什么时候用 Python 而不是 Java？</strong><br> A：一次性脚本、数据处理、快速验证、某些 SDK 只有 Python；长期中台、强事务、团队规范用 Java。</p><hr><h2 id="基础" tabindex="-1">基础 <a class="header-anchor" href="#基础" aria-label="Permalink to “基础”">​</a></h2><p><strong>Q：list / tuple / dict / set？</strong><br> A：list 可变序列；tuple 不可变；dict 键值；set 去重与成员判断。</p><p><strong>Q：浅拷贝深拷贝？</strong><br> A：浅拷贝共享内层可变对象；深拷贝用 <code>deepcopy</code>。嵌套结构改之前要想清。</p><p><strong>Q：<code>*args</code> <code>**kwargs</code>？</strong><br> A：可变位置/关键字参数，包装函数、装饰器、转发参数时用。</p><p><strong>Q：装饰器？</strong><br> A：函数包函数，复用日志、计时、重试等横切逻辑。</p><p><strong>Q：生成器？</strong><br> A：<code>yield</code> 惰性产出，省内存，适合大文件逐行处理。</p><hr><h2 id="并发" tabindex="-1">并发 <a class="header-anchor" href="#并发" aria-label="Permalink to “并发”">​</a></h2><p><strong>Q：GIL？</strong><br> A：CPython 同一时刻基本一个线程跑字节码；CPU 密集用多进程；IO 密集线程/asyncio 仍有价值。</p><p><strong>Q：多线程一定快吗？</strong><br> A：不一定。看是 IO 还是 CPU；还要看锁与任务切分。</p><hr><h2 id="工程" tabindex="-1">工程 <a class="header-anchor" href="#工程" aria-label="Permalink to “工程”">​</a></h2><p><strong>Q：依赖怎么管理？</strong><br> A：venv 隔离 + requirements 或 poetry/uv 锁版本；密钥走环境变量。</p><p><strong>Q：调接口注意什么？</strong><br> A：timeout、错误分类、幂等才重试、别把 Key 写进代码。</p><hr><h2 id="项目-自备一句" tabindex="-1">项目（自备一句） <a class="header-anchor" href="#项目-自备一句" aria-label="Permalink to “项目（自备一句）”">​</a></h2><p><strong>Q：项目里 Python 干什么？</strong><br> A：用 <a href="./project-story.html">项目讲述</a> 填空；没有就说学习脚本 + 计划用在采集/AI 调用。</p>',24)])])}const b=a(n,[["render",s]]);export{g as __pageData,b as default};
